import{_ as t,o as r,c as o,a2 as l}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"方塊記錄查詢","description":"方塊紀錄與查詢，讓你能檢查你的資產有沒有被人動過。","frontmatter":{"title":"方塊記錄查詢","description":"方塊紀錄與查詢，讓你能檢查你的資產有沒有被人動過。"},"headers":[],"relativePath":"feature/core_protect/index.md","filePath":"feature/core_protect.md"}'),a={name:"feature/core_protect/index.md"};function d(i,e,c,n,s,p){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="方塊紀錄查詢" tabindex="-1">方塊紀錄查詢 <a class="header-anchor" href="#方塊紀錄查詢" aria-label="Permalink to &quot;方塊紀錄查詢&quot;">​</a></h1><p>使用插件：<a href="https://www.spigotmc.org/resources/coreprotect.8631/" target="_blank" rel="noreferrer">CoreProtect</a>(官方連結，英文)</p><h2 id="查詢方塊建造-破壞紀錄" tabindex="-1">查詢方塊建造/破壞紀錄 <a class="header-anchor" href="#查詢方塊建造-破壞紀錄" aria-label="Permalink to &quot;查詢方塊建造/破壞紀錄&quot;">​</a></h2><p>如果家裡被破壞可以使用這些指令查詢是誰破壞的<br> 並將分流座標及記錄 回報至<a href="/discord/">Discord</a><a href="/apply/report/">🚔檢舉回報</a>並等候管理員處理</p><ul><li><code>/co i</code><b>開啟/關閉查詢功能</b><ul><li><b>對方塊點左鍵：</b>查詢該方塊位置的建造/破壞紀錄</li><li><b>對方塊點右鍵：</b>查詢相鄰方塊位置的建造/破壞紀錄、容器的物品流向</li><li>查詢功能關閉前無法正常建造/破壞方塊</li></ul></li><li><code>/co near</code><b>查詢你所在位置附近的事件</b><ul><li>查詢範圍為玩家所在位置半徑五公尺(格)內</li><li>可查詢方塊建造/破壞、丟出/撿起物品、殺害生物等事件</li></ul></li><li><code>/co l</code><b>進階搜尋功能</b><ul><li>使用方式詳見<a href="https://docs.coreprotect.net/commands/" target="_blank" rel="noreferrer">官方介紹</a>(英文)</li><li>通常用不太到，前兩個指令就夠用了</li><li>玩家使用<code>u:</code>參數時僅有查詢自己的權限，無法查詢別人的紀錄</li></ul></li><li><code>/co l &lt;page&gt;</code><b>指定頁數查詢</b><ul><li>在使用<code>/co i</code>、<code>/co near</code>及<code>/co l</code>後，可進一步使用此指令查詢指定頁數的紀錄</li><li>玩家使用<code>/co l &lt;page&gt;</code>查詢頁數時，僅可查詢9999頁以內的資料</li></ul></li></ul><h2 id="紀錄儲存期限" tabindex="-1">紀錄儲存期限 <a class="header-anchor" href="#紀錄儲存期限" aria-label="Permalink to &quot;紀錄儲存期限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分流</th><th>時間</th></tr></thead><tbody><tr><td>主伺服</td><td>永不清除</td></tr><tr><td>設施服(一)(二)</td><td>60天</td></tr><tr><td>設施服(三)</td><td>30天</td></tr><tr><td>資源服</td><td>14天</td></tr></tbody></table><ul><li>檢舉以有辦法查詢到破壞者為主，若紀錄過於久遠以至於資料清除，無法檢舉與還原</li><li>請玩家定期巡視自己的建築與資產完整性</li></ul>',8)])])}const _=t(a,[["render",d]]);export{u as __pageData,_ as default};
